export const LOCALES = { ru: 'ru-RU', pl: 'pl-PL' };
export const MESSAGES = Object.fromEntries(['ru', 'pl'].map((language, index) => [language, Object.fromEntries(entries.map(row => [row[0], row[index + 1]]))]));
export function translate(language, key, parameters = {}) {
  const message = MESSAGES[language]?.[key] ?? MESSAGES.ru[key];
  if (message === undefined) throw new Error(`Missing translation: ${key}`);
  return message.replace(/\{(\w+)\}/g, (_, name) => String(parameters[name] ?? `{${name}}`));
}

// Building IDs follow the EGiB pattern unit_9.obręb.parcel.building_BUD; unit names are the four Kraków cadastral units.
const CADASTRAL_UNITS = { '126102': 'Krowodrza', '126103': 'Nowa Huta', '126104': 'Podgórze', '126105': 'Śródmieście' };
export function roofParts(id) {
  const [unit, section, parcel, building] = String(id ?? '').split('.');
  if (!parcel || !building?.endsWith('_BUD')) return null;
  const code = unit.split('_')[0];
  return { unit: CADASTRAL_UNITS[code] || code, section: String(Number(section) || section), parcel, building: building.replace('_BUD', '') };
}
export function roofLabel(language, id) {
  const parts = roofParts(id);
  return parts ? translate(language, 'roofName', parts) : translate(language, 'roof', { id: String(id ?? '—') });
}
export function roofPlace(language, id) {
  const parts = roofParts(id);
  return parts ? translate(language, 'section', parts) : '';
}
